def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def get_list(v):
        return v if isinstance(v, list) else ([] if v is None else list(v) if isinstance(v, tuple) else [])

    def step_toward(a, b):
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

    def step_away(a, b):
        return [sign(a[0] - b[0]), sign(a[1] - b[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)

        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda c: manhattan(c, opp_p))
        return step_toward(self_p, target)

    if env == "territory_control":
        targets = get_list(observation.get("unclaimed_cells"))
        if not targets:
            targets = get_list(observation.get("opponent_territory"))
        if not targets:
            return step_away(self_p, opp_p) if manhattan(self_p, opp_p) <= 2 else [0, 0]

        best = None
        best_score = None
        for t in targets:
            tp = pos(t, self_p)
            score = manhattan(self_p, tp) * 2 - manhattan(opp_p, tp)
            if best is None or score < best_score:
                best = tp
                best_score = score
        return step_toward(self_p, best)

    resources = get_list(observation.get("resources"))
    if resources:
        best = None
        best_score = None
        for r in resources:
            rp = pos(r, self_p)
            score = manhattan(self_p, rp) * 2 - manhattan(opp_p, rp)
            if best is None or score < best_score:
                best = rp
                best_score = score
        return step_toward(self_p, best)

    # Fallbacks when no explicit targets exist.
    if env == "resource_collection":
        if manhattan(self_p, opp_p) <= 2:
            return step_away(self_p, opp_p)
        return [0, 0]

    return [0, 0]

